export class EventBus{constructor(){this.listeners=new Map();this.history=[]}on(name,fn){if(!this.listeners.has(name))this.listeners.set(name,new Set());this.listeners.get(name).add(fn);return()=>this.listeners.get(name)?.delete(fn)}emit(name,payload={}){this.history.push({name,payload});if(this.history.length>100)this.history.shift();for(const fn of this.listeners.get(name)||[])fn(payload)}}
